return page.evaluate(() => {
  const h = document.querySelector("#P");
  const out = {tag: h && h.tagName};
  let sec = h && (h.closest("section") || h.parentElement);
  const links = [...sec.querySelectorAll("a")].map(a=>a.textContent.trim());
  out.links = links; out.n = links.length;
  out.child = links.filter(t=>/child/i.test(t));
  return out;
});
